const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const northernTablelands = ee.Geometry.Polygon(
    [[[151.0, -29.5],
      [152.5, -29.5],
      [152.5, -31.5],
      [151.0, -31.5]]], null, false);
  const targetDate = '2025-08-02';
  const startDate = ee.Date(targetDate).advance(-3, 'day');
  const endDate = ee.Date(targetDate).advance(3, 'day');

  // 2. Data Acquisition - Try MODIS Terra first (primary snow product)
  let modisTerra = ee.ImageCollection('MODIS/006/MOD10A1')
    .filterBounds(northernTablelands)
    .filterDate(startDate, endDate);
  let terraSize = modisTerra.size().getInfo();
  console.log(`MODIS Terra images (3-day window): ${terraSize}`);

  let img = null;
  let collectionName = '';
  if (terraSize > 0) {
    img = modisTerra.first();
    collectionName = 'MODIS Terra';
  } else {
    // Try MODIS Aqua
    let modisAqua = ee.ImageCollection('MODIS/006/MYD10A1')
      .filterBounds(northernTablelands)
      .filterDate(startDate, endDate);
    let aquaSize = modisAqua.size().getInfo();
    console.log(`MODIS Aqua images (3-day window): ${aquaSize}`);
    if (aquaSize > 0) {
      img = modisAqua.first();
      collectionName = 'MODIS Aqua';
    } else {
      // Try Sentinel-2 with cloud masking
      let sentinel2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(northernTablelands)
        .filterDate(startDate, endDate)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));
      let s2Size = sentinel2.size().getInfo();
      console.log(`Sentinel-2 images (3-day window, <30% cloud): ${s2Size}`);
      if (s2Size > 0) {
        img = sentinel2.first();
        collectionName = 'Sentinel-2';
      } else {
        // Try Landsat 8
        let landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
          .filterBounds(northernTablelands)
          .filterDate(startDate, endDate);
        let l8Size = landsat8.size().getInfo();
        console.log(`Landsat 8 images (3-day window): ${l8Size}`);
        if (l8Size > 0) {
          img = landsat8.first();
          collectionName = 'Landsat 8';
        } else {
          // Try Landsat 9
          let landsat9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
            .filterBounds(northernTablelands)
            .filterDate(startDate, endDate);
          let l9Size = landsat9.size().getInfo();
          console.log(`Landsat 9 images (3-day window): ${l9Size}`);
          if (l9Size > 0) {
            img = landsat9.first();
            collectionName = 'Landsat 9';
          }
        }
      }
    }
  }

  // If no image found in any collection
  if (!img) {
    console.log('No images found in any collection for the date/location.');
    console.log('<answer>C1</answer>');
    return;
  }

  console.log(`Using collection: ${collectionName}`);

  // 3. Snow Detection Processing
  let snowMask = null;
  if (collectionName.includes('MODIS')) {
    // MODIS: NDSI_Snow_Cover > 0 with quality band (0-1 good, 2-3 poor)
    let snowCover = img.select('NDSI_Snow_Cover');
    let quality = img.select('NDSI_Snow_Cover_Basic_QA').lt(2); // 0 and 1 are acceptable
    snowMask = snowCover.gt(0).updateMask(quality);
  } else {
    // Sentinel-2 or Landsat: Compute NDSI
    let nir = img.select('B3'); // Green band
    let swir = collectionName === 'Sentinel-2' ? img.select('B11') : img.select('B6'); // SWIR band
    let ndsi = nir.subtract(swir).divide(nir.add(swir)).rename('NDSI');
    // Threshold for snow (commonly > 0.4)
    snowMask = ndsi.gt(0.4);
    // Cloud masking for Sentinel-2 (QA60 band)
    if (collectionName === 'Sentinel-2') {
      let qa = img.select('QA60');
      let cloudMask = qa.bitwiseAnd(1 << 10).eq(0)  // Clear bit 10 (clouds)
        .and(qa.bitwiseAnd(1 << 11).eq(0)); // Clear bit 11 (cirrus)
      snowMask = snowMask.updateMask(cloudMask);
    }
    // Cloud masking for Landsat (QA_PIXEL band)
    if (collectionName.startsWith('Landsat')) {
      let qa = img.select('QA_PIXEL');
      let cloudMask = qa.bitwiseAnd(1 << 3).eq(0)  // Clear bit 3 (cloud)
        .and(qa.bitwiseAnd(1 << 4).eq(0)); // Clear bit 4 (cloud shadow)
      snowMask = snowMask.updateMask(cloudMask);
    }
  }

  // 4. Count valid pixels and snow pixels
  let validCount = snowMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northernTablelands,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover' || 'NDSI').getInfo() || 0;

  let snowCount = snowMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: northernTablelands,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover' || 'NDSI').getInfo() || 0;

  console.log(`Valid pixels: ${validCount}`);
  console.log(`Snow pixels: ${snowCount}`);

  // 5. Validation & Final Answer
  if (validCount === 0) {
    console.log('<answer>C2</answer>');
  } else if (snowCount === null || snowCount === undefined || isNaN(snowCount)) {
    console.log('<answer>C3</answer>');
  } else if (snowCount > 0) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
